import type { LucideIcon } from 'lucide-react';
import type { HTMLAttributes, ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { EMPTY_STATE_ICON_SIZE, emptyStateVariants, type EmptyStateVariantProps } from './emptyState.variants';

export interface EmptyStateProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'title'>, EmptyStateVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Neutral icon in a soft halo (a lucide icon component). */
  icon?: LucideIcon;
  title: ReactNode;
  /** Heading level that fits the page outline. */
  titleAs?: 'h2' | 'h3' | 'h4';
  description?: ReactNode;
  /** Main call to action (e.g. a primary Button). */
  primaryAction?: ReactNode;
  /** Secondary action shown after the primary one. */
  secondaryAction?: ReactNode;
  /** Extra content under the actions (templates, links…). */
  children?: ReactNode;
}

/** Placeholder for a list, table or page with nothing to show yet: why, and what to do next. */
export function EmptyState({
  icon: Icon,
  title,
  titleAs: Heading = 'h3',
  description,
  primaryAction,
  secondaryAction,
  size,
  bordered,
  className,
  children,
  ...props
}: EmptyStateProps) {
  const s = emptyStateVariants({ size, bordered });
  return (
    <div className={cn(s.root(), className)} {...props}>
      {Icon && (
        <div className={s.icon()}>
          <Icon size={EMPTY_STATE_ICON_SIZE[size ?? 'md']} aria-hidden />
        </div>
      )}
      <Heading className={cn(s.title(), !Icon && 'mt-0')}>{title}</Heading>
      {description != null && <p className={s.description()}>{description}</p>}
      {(primaryAction != null || secondaryAction != null) && (
        <div className={s.actions()}>
          {primaryAction}
          {secondaryAction}
        </div>
      )}
      {children}
    </div>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

export const emptyStateVariants = tv({
  slots: {
    root: 'mx-auto flex w-full flex-col items-center justify-center text-center',
    icon: 'grid place-items-center bg-secondary/70 text-muted-foreground ring-1 ring-border',
    title: 'font-semibold tracking-tight text-foreground',
    description: 'text-muted-foreground',
    actions: 'flex flex-wrap items-center justify-center gap-2',
  },
  variants: {
    size: {
      sm: { root: 'max-w-sm px-4 py-6', icon: 'size-10 rounded-xl', title: 'mt-3 text-[14px]', description: 'mt-1 text-[12.5px] leading-5', actions: 'mt-4' },
      md: { root: 'max-w-md px-6 py-10', icon: 'size-12 rounded-2xl', title: 'mt-4 text-[15px]', description: 'mt-1.5 text-[13px] leading-6', actions: 'mt-5' },
      lg: { root: 'max-w-lg px-6 py-16', icon: 'size-14 rounded-2xl', title: 'mt-5 text-[17px]', description: 'mt-2 text-[14px] leading-6', actions: 'mt-6' },
    },
    bordered: {
      true: { root: 'max-w-none rounded-lg border border-dashed border-border' },
    },
  },
  defaultVariants: { size: 'md', bordered: false },
});

export type EmptyStateVariantProps = VariantProps<typeof emptyStateVariants>;

/** Icon size (px) per empty-state size. */
export const EMPTY_STATE_ICON_SIZE = { sm: 18, md: 22, lg: 26 } as const;

export { EmptyState, type EmptyStateProps } from './EmptyState';
export { emptyStateVariants, EMPTY_STATE_ICON_SIZE, type EmptyStateVariantProps } from './emptyState.variants';
export { doc as emptyStateDoc } from './EmptyState.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'EmptyState',
  group: 'Feedback',
  status: 'stable',
  description: 'Placeholder for an empty list, table or page: a neutral icon halo, a title, a short explanation and primary / secondary actions. Three sizes and an optional dashed border.',
  tokens: ['secondary', 'border', 'foreground', 'muted-foreground'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
